import os
from pathlib import Path
PROJECT_ROOT=Path(os.environ["PROJECT_ROOT"])
import json
from datetime import datetime,timezone
import numpy as np,pandas as pd,anndata as ad
run=PROJECT_ROOT/'runs/20261106_v7_QC_clean_reannotation_v1';o=run/'stage_f_Mast_expanded_context_v1';a=ad.read_h5ad(run/'stage_c_clean_views/Mast/Mast_clean_raw.h5ad');md=pd.read_csv(run/'stage_d_Mast_clean_refit/metadata_PRIVATE.tsv.gz',sep='\t',index_col='cell_id');q=pd.read_pickle(run/'stage_c_clean_views/Mast_cleaning_decisions_PRIVATE.pkl.gz').loc[a.obs_names].copy();assert a.obs_names.equals(md.index)
panels={'lymphoid_context':['CD2','CD7','IL7R','KLRB1','NKG7','GNLY','PRF1','KLRD1','NCR1'],'inflammatory_context':['LYZ','AIF1','S100A8','S100A9'],'acinar_context':['CEL','PLA2G1B','CTRC','PRSS1','PRSS2','SPINK1'],'endocrine_context':['CHGA','CHGB','SYP','PCSK1N','CPE','FXYD2'],'neural_context':['MAPT','NEFL','NEFM','NCAM1','TACC2','CACNA1A']};core=['TPSAB1','TPSB2','CPA3','KIT','MS4A2'];genes=list(dict.fromkeys(core+[g for z in panels.values() for g in z]));ii=a.var_names.get_indexer(genes);assert (ii>=0).all();x=a.X[:,ii].toarray();ix={g:i for i,g in enumerate(genes)};total=np.asarray(a.X.sum(axis=1)).ravel();q['clean_cluster']=md['source_snn_res.0.4'].to_numpy();q['Mast_core_RNA_fraction']=x[:,[ix[g] for g in core]].sum(axis=1)/np.maximum(total,1);rows=[]
for key,gg in panels.items():
 xx=x[:,[ix[g] for g in gg]];q[key+'_program_review']=((xx>=1).sum(axis=1)>=3)|((xx>=2).sum(axis=1)>=2);q[key+'_RNA_fraction']=xx.sum(axis=1)/np.maximum(total,1)
 for cl,t in q.groupby('clean_cluster',observed=True):
  pos=t[key+'_program_review'];pct=pd.to_numeric(t.doublet_within_sample_method_percentile,errors='coerce');rows.append({'cluster':int(cl),'context':key,'n_cells':len(t),'n_context_positive':int(pos.sum()),'n_context_positive_original_doublet_percentile95':int((pos&(pct>=.95)).sum()),'context_RNA_fraction_median':float(t[key+'_RNA_fraction'].median()),'context_RNA_fraction_p95':float(t[key+'_RNA_fraction'].quantile(.95)),'Mast_core_RNA_fraction_median':float(t.Mast_core_RNA_fraction.median()),'decontx_median':float(pd.to_numeric(t.decontx_contamination,errors='coerce').median()),'original_doublet_percentile_median':float(pct.median())})
q.to_pickle(o/'additional_context_cellwise_PRIVATE.pkl.gz');pd.DataFrame(rows).to_csv(o/'additional_context_QC_summary.tsv',sep='\t',index=False,na_rep='NA')
out={'status':'completed_additional_RNA_context_review_flags_only','UTC':datetime.now(timezone.utc).isoformat(),'n_cells':len(q),'n_clusters':q.clean_cluster.nunique(),'n_aggregate_records':len(rows),'no_new_QC_exclusions':True,'limits':'Context programs are nonexclusive, not positive lineage classifiers. FCER1G/TYROBP shared with Mast are omitted from inflammatory positive flag. Pan-MC reference C9 itself includes CCL5/IL32/GZMB; lymphoid-like association is not automatically a doublet. Source-aware RNA fractions, old scores and further identity review are separate.'};out['n_clusters']=int(out['n_clusters']);(o/'additional_context_complete.json').open('x').write(json.dumps(out,indent=2));print(json.dumps(out))
